-- Variants, live variants and price per experience shown on a Vatican (CE 189) page or matched to one of its clusters.
SELECT
    CAST(experience_id AS STRING) AS experience_id,
    ANY_VALUE(primary_sub_category_name) AS sub_category,
    COUNT(DISTINCT variant_id) AS variants,
    COUNT(DISTINCT IF(is_available, variant_id, NULL)) AS live_variants,
    MIN(IF(is_available, listing_final_price, NULL)) AS from_price

FROM `headout-analytics.analytics_reporting.dim_variants`

WHERE CAST(experience_id AS STRING) IN UNNEST(SPLIT('3063,3137,3161,3166,3225,3228,3241,3361,3383,3725,3832,3853,3865,3876,3937,4019,6706,6707,6730,6732,6796,7022,7023,7422,7451,7464,7491,7761,7818,7827,7953,7955,7967,7968,7969,7971,7998,8846,8847,9092,9264,9267,9378,9379,9682,9910,9993,10253,10424,10479,10480,10644,10757,15084,15143,15144,15248,15249,15315,15414,15436,15438,15487,15839,15847,15856,15947,16135,16466,16551,16552,17798,18300,20032,20082,20195,25598,28530,28867,28869,28870,29116,29277,29998,31786,32197,33032,36101,36212,36265,36297,36641,36702,38585,39151,39152,42091,42093,42095,42741,42841,42842,43592,45695,46090,47039,47113,47114,47134,48055,48477,48825,50331,53876,54121,54334,54814,56096,56793,57134,57182,57897,58104,58636,59617,59961,59995,60100'))

GROUP BY 1
